import numpy as np


def sigmoid(x):
    return 1 / (1 + np.exp(-x))


def predict_proba(X, w, b):
    return sigmoid(X @ w + b)


def train(X, y, lr=1.0, epochs=2000):
    w = np.zeros(X.shape[1])
    b = 0.0
    for _ in range(epochs):
        p = predict_proba(X, w, b)
        error = p - y
        w -= lr * X.T @ error / len(y)
        b -= lr * error.mean()
    return w, b


X = np.array([[0, 0], [0, 1], [1, 0], [1, 1]], dtype=float)
y_and = np.array([0, 0, 0, 1], dtype=float)

result = train(X, y_and)
if result is None:
    print("train() returned None")
else:
    w, b = result
    preds = (predict_proba(X, w, b) >= 0.5).astype(int)
    print("Predictions:", preds)
